import JUDGE from "./goal/judge.txt"
import KICKOFF from "./goal/kickoff.txt"
import REMINDER from "./goal/reminder.txt"

export const MAX_OBJECTIVE = 4_000
export const MAX_ROUNDS = 50
export const MAX_STALLS = 3
