  id: "opencode.goal",
  effect: Effect.fn(function* (ctx) {
    const read = Effect.fn("GoalPlugin.read")(function* (sessionID: string) {
      return Option.getOrUndefined(decodeState(yield* ctx.storage.get(PREFIX + sessionID)))
    })

